mapper.insert:
insert into eg_check_account_detail_result(record_id, period_code, currency_type, org_id, account_code, contract_code, client_code, account_remain_balance, detail_remain_balance, diff_flag, diff_balance, del_flag, create_by, create_time, update_by, update_time) select ${param.recordId} as record_id, tab_all.period_code, tab_all.currency_type,tab_all.org_id,tab_all.account_code , tab_all.contract_code ,tab_all.client_code ,tab_all.account_remain_balance, tab_all.detail_remain_balance, case when tab_all.account_remain_balance = tab_all.detail_remain_balance then '0' else '1' end diff_flag, tab_all.account_remain_balance-tab_all.detail_remain_balance as diff_balance, ${param.delFlag}, ${param.createBy}, now(), ${param.updateBy}, now() from (
select eaab.period_code,eaab.currency_code currency_type,eaab.org_id,eaab.account_code , eaab.contract_code ,eaab.client_code ,eaab.month_end_debit_balance account_remain_balance,ecbl.${item.queryField} detail_remain_balance from eg_account_assist_balance eaab join eg_contract_balance_latest ecbl on eaab.period_code = ecbl.period_code and eaab.org_id = ecbl.org_id and eaab.contract_code = ecbl.contract_code and eaab.client_code = ecbl.client_code where eaab.period_code = #{param.periodCode} and eaab.account_code = #{item.accountCode} and eaab.del_flag = '0' and ecbl.del_flag = '0'
) tab_all

mapper.select:
select ${param.recordId} as record_id, tab_all.period_code, tab_all.currency_type,tab_all.org_id,tab_all.account_code , tab_all.contract_code ,tab_all.client_code ,tab_all.account_remain_balance, tab_all.detail_remain_balance, case when tab_all.account_remain_balance = tab_all.detail_remain_balance then '0' else '1' end diff_flag, tab_all.account_remain_balance-tab_all.detail_remain_balance as diff_balance, ${param.delFlag}, ${param.createBy}, now(), ${param.updateBy}, now() from (
select eaab.period_code,eaab.currency_code currency_type,eaab.org_id,eaab.account_code , eaab.contract_code ,eaab.client_code ,eaab.month_end_debit_balance account_remain_balance,ecbl.${item.queryField} detail_remain_balance from eg_account_assist_balance eaab join eg_contract_balance_latest ecbl on eaab.period_code = ecbl.period_code and eaab.org_id = ecbl.org_id and eaab.contract_code = ecbl.contract_code and eaab.client_code = ecbl.client_code where eaab.period_code = #{param.periodCode} and eaab.account_code = #{item.accountCode} and eaab.del_flag = '0' and ecbl.del_flag = '0'
) tab_all
